namespace NcnHelper {
public static class Json {
 public static JavaScriptSerializer S(){return new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue,RecursionLimit=150};}
 public static Dictionary<string,object> Read(string text){return S().Deserialize<Dictionary<string,object>>(text);}
 public static string Write(object x){return S().Serialize(x);}
 public static Dictionary<string,object> Obj(Dictionary<string,object> d,string key){object x;if(!d.TryGetValue(key,out x)||!(x is Dictionary<string,object>))throw new Exception("Unknown NightCityNet structure: "+key);return (Dictionary<string,object>)x;}
 public static string Str(Dictionary<string,object> d,string key){object x;return d.TryGetValue(key,out x)&&x!=null?Convert.ToString(x):"";}
}
// Lexical spans preserve every untouched value, key, comment field and whitespace.
public class JsonPatch {
 string s;int i;Dictionary<string,Tuple<int,int>> spans=new Dictionary<string,Tuple<int,int>>();
 void Ws(){while(i<s.Length&&Char.IsWhiteSpace(s[i]))i++;}
 string String(){int a=i++;while(i<s.Length){char c=s[i++];if(c=='\\'){if(i>=s.Length)throw new Exception("JSON escape");i++;}else if(c=='"')return Json.S().Deserialize<string>(s.Substring(a,i-a));}throw new Exception("JSON string");}
 static string Escape(string k){return k.Replace("~","~0").Replace("/","~1");}
 void Value(string path){Ws();int start=i;if(s[i]=='{'){i++;Ws();HashSet<string> seen=new HashSet<string>();if(s[i]!='}')while(true){Ws();string k=String();if(!seen.Add(k))throw new Exception("Duplicate JSON key: "+path+"/"+k);Ws();if(s[i++]!=':')throw new Exception("JSON colon");Value(path+"/"+Escape(k));Ws();if(s[i]=='}')break;if(s[i++]!=',')throw new Exception("JSON comma");}i++;}
 else if(s[i]=='['){i++;Ws();int n=0;if(s[i]!=']')while(true){Value(path+"/"+(n++));Ws();if(s[i]==']')break;if(s[i++]!=',')throw new Exception("JSON comma");}i++;}
 else if(s[i]=='"')String();else while(i<s.Length&&!Char.IsWhiteSpace(s[i])&&",]}".IndexOf(s[i])<0)i++;
 spans.Add(path,Tuple.Create(start,i-start));}
 public static string Apply(string input,Dictionary<string,object> values){Json.Read(input);var p=new JsonPatch{s=input};p.Value("");p.Ws();if(p.i!=input.Length)throw new Exception("JSON trailing data");var edits=new List<Tuple<int,int,string>>();foreach(var v in values){Tuple<int,int> pos;if(!p.spans.TryGetValue(v.Key,out pos))throw new Exception("This mod version has no setting "+v.Key+". Compatibility needs checking.");edits.Add(Tuple.Create(pos.Item1,pos.Item2,Json.Write(v.Value)));}foreach(var e in edits.OrderByDescending(x=>x.Item1))input=input.Remove(e.Item1,e.Item2).Insert(e.Item1,e.Item3);Json.Read(input);return input;}
}
public class Choice {public string Text,Value;public Choice(string t,string v){Text=t;Value=v;}public override string ToString(){return Text;}}
public class Options {
 public string Game,Whisper="",Language="",SttLanguage=""; public CitySetup Studio=null;
 public int Stt=0,Profanity=0,Mouth=0,Speed=0,Endings=0; public bool RequireMultilingual=false;
}
public class Change {
 public string Target,Source,BeforeHash,AfterHash; public byte[] Bytes;public bool Existed,Delete;
 public string HashNew(){return Bytes!=null?Core.Hash(Bytes):Core.HashFile(Source);}
}
public class Plan {public string Game;public List<Change> Changes=new List<Change>();public List<string> Summary=new List<string>();}
public static class Core {
 public static string WhisperYaml(string text,string model,string language){string lang=language==""?"auto":language;if(!Regex.IsMatch(lang,@"^[a-z]{2,4}$"))throw new Exception("Unknown Whisper language.");if(Regex.Matches(text,@"(?m)^language:[^\r\n]*").Count!=1||Regex.Matches(text,@"(?m)^backend:[^\r\n]*").Count!=1)throw new Exception("Unknown STT.yaml structure.");text=Regex.Replace(text,@"(?m)^language:[^\r\n]*","language: "+lang);text=Regex.Replace(text,@"(?m)^backend:[^\r\n]*","backend: whisper");var block=Regex.Match(text,@"(?ms)^whisper:\r?\n.*?(?=^\S|\z)");if(!block.Success||Regex.Matches(block.Value,@"(?m)^  model:[^\r\n]*").Count!=1)throw new Exception("Local model block not found in STT.yaml.");string edited=Regex.Replace(block.Value,@"(?m)^  model:[^\r\n]*","  model: "+model);return text.Remove(block.Index,block.Length).Insert(block.Index,edited);}
 public static string Base=AppDomain.CurrentDomain.BaseDirectory;
 public static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static string HashFile(string p){using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static string Mod(string root){return Path.Combine(root,@"bin\x64\plugins\cyber_engine_tweaks\mods\nightcitynet");}
 public static string Config(string root){return Path.Combine(Mod(root),@"data\config.json");}
 public static void GameClosed(){if(Process.GetProcessesByName("Cyberpunk2077").Length>0)throw new Exception("Close Cyberpunk before changing files. The local model can be started separately.");}
 public static void ValidateRoot(string root){if(!File.Exists(Path.Combine(root,@"bin\x64\Cyberpunk2077.exe")))throw new Exception("Choose the Cyberpunk 2077 root folder containing bin, r6 and archive.");if(!File.Exists(Config(root))||!File.Exists(Path.Combine(Mod(root),"init.lua")))throw new Exception("NightCityNet was not found here. This helper supports the CET nightcitynet mod; AI NPC LLM Companions is a different mod.");var c=Json.Read(File.ReadAllText(Config(root)));Json.Obj(c,"llm");Json.Obj(c,"stt");Json.Obj(c,"tts");}
 public static void Under(string path,string root){string p=Path.GetFullPath(path),r=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!p.StartsWith(r,StringComparison.OrdinalIgnoreCase))throw new Exception("Path is outside the selected folder.");}
 public static void NoLinks(string path,string root){Under(path,root);string cur=Path.GetFullPath(path);while(cur.Length>Path.GetFullPath(root).TrimEnd('\\').Length){if((File.Exists(cur)||Directory.Exists(cur))&&(File.GetAttributes(cur)&FileAttributes.ReparsePoint)!=0)throw new Exception("Target is a symbolic link: "+cur+". This installation needs a separate compatibility check.");cur=Path.GetDirectoryName(cur);}}
 public static byte[] Encode(string text,string original){bool bom=File.Exists(original)&&File.ReadAllBytes(original).Take(3).SequenceEqual(new byte[]{239,187,191});byte[] b=new UTF8Encoding(false).GetBytes(text);return bom?new byte[]{239,187,191}.Concat(b).ToArray():b;}
 public static void Add(Plan p,string target,byte[] bytes,string source){NoLinks(target,p.Game);bool exists=File.Exists(target);var c=new Change{Target=target,Bytes=bytes,Source=source,Existed=exists,BeforeHash=exists?HashFile(target):""};c.AfterHash=c.HashNew();if(c.BeforeHash!=c.AfterHash)p.Changes.Add(c);}
 public static void ModelFile(string path,bool gguf){if(!File.Exists(path))throw new Exception("Model file not found: "+path);using(var f=File.OpenRead(path)){byte[] b=new byte[4];if(f.Read(b,0,4)!=4||(!gguf&&!b.SequenceEqual(new byte[]{108,109,103,103}))||(gguf&&Encoding.ASCII.GetString(b)!="GGUF"))throw new Exception(gguf?"Select a .gguf model, not a ZIP or HTML page.":"Select a whisper.cpp ggml-*.bin model, not a ZIP or HTML page.");}}
 public static Uri LocalUrl(string s){Uri u;if(!Uri.TryCreate(s.TrimEnd('/'),UriKind.Absolute,out u)||u.Scheme!="http"||!u.IsLoopback||u.UserInfo!=""||u.Query!=""||u.Fragment!="")throw new Exception("Local server must use http://127.0.0.1:port or localhost. Cloud addresses are not accepted here.");return u;}
 public static string Net(string url,string body,int seconds){var u=LocalUrl(url);var r=(HttpWebRequest)WebRequest.Create(u);r.Proxy=null;r.Timeout=seconds*1000;r.ReadWriteTimeout=seconds*1000;if(body!=null){r.Method="POST";r.ContentType="application/json";byte[] b=Encoding.UTF8.GetBytes(body);r.ContentLength=b.Length;using(var s=r.GetRequestStream())s.Write(b,0,b.Length);}try{using(var resp=r.GetResponse())using(var sr=new StreamReader(resp.GetResponseStream()))return sr.ReadToEnd();}catch(WebException){throw new Exception("Local server did not respond or rejected the request: "+u.GetLeftPart(UriPartial.Authority)+". Check that it is running and the model name is correct.");}}
 public static string Overlay(string text,string kind,string content){string start="{# NCN_HELPER_"+kind+"_BEGIN #}",end="{# NCN_HELPER_"+kind+"_END #}";int a=text.IndexOf(start,StringComparison.Ordinal),b=text.IndexOf(end,StringComparison.Ordinal);if((a<0)!=(b<0)||a>=0&&(b<a||text.IndexOf(start,a+start.Length,StringComparison.Ordinal)>=0||text.IndexOf(end,b+end.Length,StringComparison.Ordinal)>=0))throw new Exception("The helper prompt section is damaged. Restore it from a backup.");if(a>=0){int cut=a;while(cut>0&&(text[cut-1]=='\r'||text[cut-1]=='\n'))cut--;text=text.Remove(cut,b+end.Length-cut);}if(content!=null&&content!="")text=text.TrimEnd()+"\r\n\r\n"+start+"\r\n"+content+"\r\n"+end+"\r\n";return text;}
 public static string LanguagePrompt(string code){if(code=="uk-ru")return "## Dialogue language\nSpeak Ukrainian or Russian, or a natural colloquial mixture of both, matching the player when possible. Ukrainian/Russian surzhyk and code-switching are explicitly welcome in this mode. Preserve all native emotion/action/addressee tags, names and engine syntax; do not translate control tags. Do not announce a language change.\n## Alternate fictional setting for this UA/RU mode only\nУ цьому вигаданому мемному сценарії Найт-Сіті — місто на заході України, далеко від фронту. У світі сценарію в Україні триває війна. Це тилове місто, а не зона бойових дій: не вигадуй бої, обстріли чи прифронтову обстановку в поточній сцені без її подій. Тут є люди, які ховаються від мобілізації. Тимчасова роль Ві: він ходить вулицями та шукає ухилянтів. NPC можуть підозрювати його наміри з його слів або поведінки й реагувати на це, але не читають його думок. Використовуй місцевий сленг, жарти й згадки про ТЦК, мобілізацію та фронт відповідно до сцени. Це альтернативна художня географія: вона перекриває канонічне розташування Найт-Сіті у США лише в цьому мовному режимі. Збережи кіберпанковий вигляд міста, особистості персонажів, імена й факти їхніх стосунків. Гравець сам вирішує, кого перевіряти і що робити; не вигадуй за нього затримань, знайдених людей, документів чи завершених дій. Не перетворюй цей пресет на новий квестовий факт або спогад.\n";var names=new Dictionary<string,string>{{"en","English"},{"uk","Ukrainian"},{"pl","Polish"},{"de","German"},{"fr","French"},{"es","Latin American Spanish"},{"it","Italian"},{"pt","Brazilian Portuguese"},{"ja","Japanese"}};return "## Dialogue language\nSpeak all audible dialogue and ordinary narration in "+names[code]+". Express the same character, emotions and meaning naturally in that language. Keep proper names, native action names, addressee tags, emotion tags, JSON fields, placeholders and engine syntax exactly as required by the other templates. Never translate or speak control tags. Use this language even when the player speaks another language or the transcript is in English. Translate the meaning of dialogue examples rather than copying their English wording. This language setting is not a new event, memory or relationship; never announce it.";}
 public static void PatchJson(Plan p,string path,Dictionary<string,object> fields){var old=p.Changes.FirstOrDefault(x=>String.Equals(x.Target,path,StringComparison.OrdinalIgnoreCase));string text=old==null?File.ReadAllText(path):Encoding.UTF8.GetString(old.Bytes).TrimStart((char)0xfeff);byte[] bytes=Encode(JsonPatch.Apply(text,fields),path);if(old==null)Add(p,path,bytes,null);else{old.Bytes=bytes;old.AfterHash=old.HashNew();}}
 public static Plan Build(Options o){ValidateRoot(o.Game);Plan p=new Plan{Game=Path.GetFullPath(o.Game)};
 if(o.Stt==1){string name=Path.GetFileName(o.Whisper);if(!Regex.IsMatch(name,@"^ggml-[a-zA-Z0-9_.-]+\.bin$"))throw new Exception("Whisper requires a file named ggml-MODEL.bin.");ModelFile(o.Whisper,false);string id=name.Substring(5,name.Length-9);if(Regex.IsMatch(id,@"\.en(?:-|$)")&&(o.RequireMultilingual||(o.SttLanguage!=""&&o.SttLanguage!="en")))throw new Exception("An .en model recognizes English only. Choose multilingual Whisper or English input.");string native=Path.Combine(o.Game,@"red4ext\plugins\nightcitynet\stt");foreach(string dll in new[]{"FatelessAiEngine.dll","whisper.dll"})if(!File.Exists(Path.Combine(native,dll)))throw new Exception("Bundled Whisper engine missing: "+dll+". Install it from the NightCityNet distribution.");string target=Path.Combine(Mod(o.Game),@"data\models\"+name);if(!String.Equals(Path.GetFullPath(target),Path.GetFullPath(o.Whisper),StringComparison.OrdinalIgnoreCase))Add(p,target,null,o.Whisper);string yaml=Path.Combine(Mod(o.Game),@"data\stt\STT.yaml");if(File.Exists(yaml))Add(p,yaml,Encode(WhisperYaml(File.ReadAllText(yaml),id,o.SttLanguage),yaml),null);string config=Config(o.Game);var speech=new Dictionary<string,object>{{"/stt/backend","local"},{"/stt/local_model",id},{"/stt/language",o.SttLanguage}};PatchJson(p,config,speech);p.Summary.Add("Whisper model: "+id+". In NightCityNet select local and local_model = "+id+". Verify this model in game.");}


 if(o.Language!=""||o.Profanity!=0){string templateDir=Path.Combine(Mod(o.Game),@"data\templates");string settings=Path.Combine(templateDir,"settings.tpl");if(!File.Exists(settings))throw new Exception("data/templates/settings.tpl was not found.");string effective=o.Language=="reset"?"en":o.Language!=""?o.Language:Profanity.CurrentLanguage(o.Game);string sw=o.Profanity==0||o.Profanity==4?"":Profanity.Prompt(o.Profanity,effective,o.Speed==1||(o.Speed==0&&File.ReadAllText(settings).Contains("NCN_HELPER_SPEED_BEGIN")));foreach(string name in new[]{"settings.tpl","system.tpl"}){string tpl=Path.Combine(templateDir,name);if(!File.Exists(tpl))continue;string t=File.ReadAllText(tpl);if(o.Language!="")t=Overlay(t,"LANG",o.Language=="reset"?"":LanguagePrompt(o.Language));if(o.Profanity!=0)t=Overlay(t,"SWEAR",sw);Add(p,tpl,Encode(t,tpl),null);}if(o.Profanity==3){string config=Config(o.Game);var doc=Json.Read(File.ReadAllText(config));if(Json.Obj(doc,"llm").ContainsKey("token_caps"))PatchJson(p,config,new Dictionary<string,object>{{"/llm/token_caps/reply",1024}});}p.Summary.Add("Language and style use helper-owned sections; characters and history are preserved.");}
 int speedMode=o.Speed;
 Turbo.Build(p,speedMode);
 CityPrompts.Build(p,o.Studio);
 ReplyEndings.Build(p,o.Endings);
 MouthPatch.Build(p,o.Mouth,o.Language=="reset"?"en":o.Language!=""?o.Language:Profanity.CurrentLanguage(o.Game));
 p.Changes.RemoveAll(x=>x.BeforeHash==x.AfterHash);
 p.Summary.Add("World State, profiles, memory and voice settings are preserved.");return p;}
 public static void PrivateDir(string path){Directory.CreateDirectory(path);try{var sec=new DirectorySecurity();sec.SetAccessRuleProtection(true,false);var sid=WindowsIdentity.GetCurrent().User;sec.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(path,sec);}catch{throw new Exception("Could not secure the private configuration backup. No changes were applied.");}}
 public static string Apply(Plan p){GameClosed();if(p.Changes.Count==0)return "";ValidateRoot(p.Game);string folder=Path.Combine(Base,"Backups",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));PrivateDir(folder);var rows=new List<Dictionary<string,object>>();var temps=new List<string>();var committed=new List<int>();try{for(int n=0;n<p.Changes.Count;n++){Change c=p.Changes[n];NoLinks(c.Target,p.Game);if(File.Exists(c.Target)!=c.Existed||(c.Existed&&HashFile(c.Target)!=c.BeforeHash))throw new Exception("File changed after preview. Preview again: "+Path.GetFileName(c.Target));if(c.Existed)File.Copy(c.Target,Path.Combine(folder,n+".before"));Directory.CreateDirectory(Path.GetDirectoryName(c.Target));string temp=c.Target+".ncn-helper-"+Guid.NewGuid().ToString("N")+".tmp";temps.Add(temp);if(!c.Delete){if(c.Bytes!=null)File.WriteAllBytes(temp,c.Bytes);else File.Copy(c.Source,temp);}if(!c.Delete&&HashFile(temp)!=c.AfterHash)throw new Exception("Model copy failed verification.");rows.Add(new Dictionary<string,object>{{"target",c.Target},{"before",c.BeforeHash},{"after",c.AfterHash},{"existed",c.Existed},{"backup",n+".before"}});}
 var journal=new Dictionary<string,object>{{"game",p.Game},{"state","prepared"},{"files",rows}};File.WriteAllText(Path.Combine(folder,"transaction.json"),Json.Write(journal),new UTF8Encoding(false));for(int n=0;n<p.Changes.Count;n++){var c=p.Changes[n];if(File.Exists(c.Target)!=c.Existed||c.Existed&&HashFile(c.Target)!=c.BeforeHash)throw new Exception("A file changed during installation. Operation cancelled.");if(c.Delete)File.Delete(c.Target);else if(c.Existed)File.Replace(temps[n],c.Target,null);else File.Move(temps[n],c.Target);committed.Add(n);}
 journal["state"]="applied";File.WriteAllText(Path.Combine(folder,"transaction.json"),Json.Write(journal),new UTF8Encoding(false));return folder;
 }catch{foreach(int n in committed.AsEnumerable().Reverse()){var c=p.Changes[n];if(c.Existed)AtomicCopy(Path.Combine(folder,n+".before"),c.Target);else if(File.Exists(c.Target)&&HashFile(c.Target)==c.AfterHash)File.Delete(c.Target);}throw;}finally{foreach(string t in temps)if(File.Exists(t))File.Delete(t);}}
 static void AtomicCopy(string source,string target){string tmp=target+".restore-"+Guid.NewGuid().ToString("N")+".tmp";File.Copy(source,tmp);try{if(File.Exists(target))File.Replace(tmp,target,null);else File.Move(tmp,target);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 public static string Latest(string root){string dir=Path.Combine(Base,"Backups");if(!Directory.Exists(dir))return "";foreach(string f in Directory.GetDirectories(dir).OrderByDescending(x=>x)){string path=Path.Combine(f,"transaction.json");if(!File.Exists(path))continue;var j=Json.Read(File.ReadAllText(path));if(Json.Str(j,"state")!="restored"&&String.Equals(Json.Str(j,"game"),Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase))return f;}return "";}
 public static void Restore(string root,string folder){GameClosed();ValidateRoot(root);Under(folder,Path.Combine(Base,"Backups"));string jf=Path.Combine(folder,"transaction.json");var j=Json.Read(File.ReadAllText(jf));if(!String.Equals(Json.Str(j,"game"),Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase))throw new Exception("Backup belongs to another installation.");var rows=((IEnumerable)j["files"]).Cast<object>().Select(x=>(Dictionary<string,object>)x).ToArray();foreach(var row in rows){string t=Json.Str(row,"target");NoLinks(t,root);string h=File.Exists(t)?HashFile(t):"";if(h!=Json.Str(row,"after")&&h!=Json.Str(row,"before"))throw new Exception("File was edited after installation; automatic undo will not overwrite it: "+Path.GetFileName(t));if(Convert.ToBoolean(row["existed"])&&HashFile(Path.Combine(folder,Json.Str(row,"backup")))!=Json.Str(row,"before"))throw new Exception("Backup is damaged.");}foreach(var row in rows.Reverse()){string t=Json.Str(row,"target");if(Convert.ToBoolean(row["existed"]))AtomicCopy(Path.Combine(folder,Json.Str(row,"backup")),t);else if(File.Exists(t))File.Delete(t);}j["state"]="restored";File.WriteAllText(jf,Json.Write(j),new UTF8Encoding(false));}
}
}
